tool_schemas.implementation:
def smartthinking(thought, thoughtType=None, connections=None, requestSuggestions=None, generateVisualization=None, visualizationType=None, suggestTools=None, sessionId=None, userId=None, help=None, requestVerification=None, containsCalculations=None, visualizationOptions=None, **_extra):
    import json, os, datetime, time, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0400000" if __import__("os").path.isdir("./environment_mix/0400000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---------- helpers ----------
    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _is_iso_dt(s):
        if not isinstance(s, str) or not s:
            return False
        try:
            if s.endswith("Z"):
                datetime.datetime.fromisoformat(s[:-1])
            else:
                datetime.datetime.fromisoformat(s)
            return True
        except Exception:
            return False

    def _audit(status, used_auth=None, extra=None):
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": _gen_id("req"),
            "endpoint": "smartthinking",
            "status": status,
            "latency_ms": latency_ms,
            "timestamp": now,
            "auth_token": used_auth,
        }
        if isinstance(extra, dict):
            row.update(extra)
        audits = _load("request_logs.json")
        if not isinstance(audits, list):
            audits = []
        audits.append(row)
        _save("request_logs.json", audits)

    def _validate_bool(v, name):
        if v is None:
            return None
        if isinstance(v, bool):
            return v
        return _err("VALIDATION_ERROR", f"{name} must be boolean")

    def _validate_str(v, name, allow_empty=False):
        if v is None:
            return None
        if not isinstance(v, str):
            return _err("VALIDATION_ERROR", f"{name} must be string")
        if (not allow_empty) and v == "":
            return _err("VALIDATION_ERROR", f"{name} must not be empty")
        return v

    def _ensure_list(v, name):
        if v is None:
            return []
        if not isinstance(v, list):
            return _err("VALIDATION_ERROR", f"{name} must be array")
        return v

    # ---------- input validation ----------
    if not isinstance(thought, str) or thought == "":
        _audit("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "thought is required and must be a non-empty string")
    if len(thought) > 20000:
        _audit("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "thought exceeds maximum length (20000)")

    allowed_ttypes = {"regular", "revision", "meta", "hypothesis", "conclusion"}
    if thoughtType is None:
        thoughtType = "regular"
    if not isinstance(thoughtType, str) or thoughtType not in allowed_ttypes:
        _audit("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "thoughtType must be one of: regular, revision, meta, hypothesis, conclusion")

    v = _validate_str(sessionId, "sessionId")
    if isinstance(v, dict) and "error" in v:
        _audit("error", extra={"error_code": "VALIDATION_ERROR"})
        return v
    sessionId = v

    v = _validate_str(userId, "userId")
    if isinstance(v, dict) and "error" in v:
        _audit("error", extra={"error_code": "VALIDATION_ERROR"})
        return v
    userId = v

    # defaults
    if requestSuggestions is None:
        requestSuggestions = False
    if generateVisualization is None:
        generateVisualization = False
    if suggestTools is None:
        suggestTools = True
    if help is None:
        help = True
    if requestVerification is None:
        requestVerification = False
    if containsCalculations is None:
        containsCalculations = False
    if visualizationType is None:
        visualizationType = "graph"

    for name, val in [
        ("requestSuggestions", requestSuggestions),
        ("generateVisualization", generateVisualization),
        ("suggestTools", suggestTools),
        ("help", help),
        ("requestVerification", requestVerification),
        ("containsCalculations", containsCalculations),
    ]:
        vv = _validate_bool(val, name)
        if isinstance(vv, dict) and "error" in vv:
            _audit("error", extra={"error_code": "VALIDATION_ERROR"})
            return vv

    allowed_viz = {"graph", "chronological", "thematic", "hierarchical", "force", "radial"}
    if not isinstance(visualizationType, str) or visualizationType not in allowed_viz:
        _audit("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "visualizationType must be one of: graph, chronological, thematic, hierarchical, force, radial")

    clist = _ensure_list(connections, "connections")
    if isinstance(clist, dict) and "error" in clist:
        _audit("error", extra={"error_code": "VALIDATION_ERROR"})
        return clist
    connections = clist
    if len(connections) > 200:
        _audit("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "connections exceeds maximum length (200)")

    if visualizationOptions is not None and not isinstance(visualizationOptions, dict):
        _audit("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "visualizationOptions must be an object")

    # validate vizOptions size and key sub-constraints (only those specified)
    if visualizationOptions is not None:
        try:
            vo_ser = json.dumps(visualizationOptions, ensure_ascii=False, separators=(",", ":"))
        except (TypeError, ValueError):
            _audit("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "visualizationOptions must be JSON-serializable")
        if len(vo_ser.encode("utf-8")) > 65536:
            _audit("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "visualizationOptions exceeds 64KB serialized")

        # metricThresholds.* must be 2-length arrays if present
        filters = visualizationOptions.get("filters") if isinstance(visualizationOptions, dict) else None
        if isinstance(filters, dict):
            mt = filters.get("metricThresholds")
            if isinstance(mt, dict):
                for k in ("confidence", "relevance", "quality"):
                    if k in mt and mt[k] is not None:
                        arr = mt[k]
                        if not (isinstance(arr, list) and len(arr) == 2 and all(isinstance(x, (int, float)) for x in arr)):
                            _audit("error", extra={"error_code": "VALIDATION_ERROR"})
                            return _err("VALIDATION_ERROR", f"visualizationOptions.filters.metricThresholds.{k} must be a 2-length number array")
        inter = visualizationOptions.get("interactivity") if isinstance(visualizationOptions, dict) else None
        if isinstance(inter, dict) and "zoomRange" in inter and inter["zoomRange"] is not None:
            zr = inter["zoomRange"]
            if not (isinstance(zr, list) and len(zr) == 2 and all(isinstance(x, (int, float)) for x in zr)):
                _audit("error", extra={"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "visualizationOptions.interactivity.zoomRange must be a 2-length number array")
        if isinstance(visualizationOptions, dict) and "maxDepth" in visualizationOptions and visualizationOptions["maxDepth"] is not None:
            md = visualizationOptions["maxDepth"]
            if not isinstance(md, (int, float)) or md < 0:
                _audit("error", extra={"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "visualizationOptions.maxDepth must be >= 0")

    # validate each connection shape and rules
    allowed_ctypes = {
        "supports","contradicts","refines","branches","derives","associates","exemplifies","generalizes","compares","contrasts",
        "questions","extends","analyzes","synthesizes","applies","evaluates","cites",
        "extended-by","analyzed-by","component-of","applied-by","evaluated-by","cited-by"
    }
    allowed_temp = {"before","after","during","concurrent"}
    allowed_cert = {"definite","high","moderate","low","speculative"}
    allowed_dir = {"unidirectional","bidirectional","multidirectional"}
    allowed_scope = {"broad","specific","partial","complete"}
    allowed_nature = {"causal","correlational","sequential","hierarchical","associative"}

    for i, c in enumerate(connections):
        if not isinstance(c, dict):
            _audit("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", f"connections[{i}] must be object")
        for req in ("targetId", "type", "strength"):
            if req not in c:
                _audit("error", extra={"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", f"connections[{i}].{req} is required")
        if not isinstance(c["targetId"], str) or c["targetId"] == "":
            _audit("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", f"connections[{i}].targetId must be non-empty string")
        if not isinstance(c["type"], str) or c["type"] not in allowed_ctypes:
            _audit("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", f"connections[{i}].type invalid")
        st = c["strength"]
        if not isinstance(st, (int, float)) or st < 0 or st > 1:
            _audit("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", f"connections[{i}].strength must be between 0 and 1")
        if "inferred" in c and c["inferred"] is not None and not isinstance(c["inferred"], bool):
            _audit("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", f"connections[{i}].inferred must be boolean")
        if "bidirectional" in c and c["bidirectional"] is not None and not isinstance(c["bidirectional"], bool):
            _audit("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", f"connections[{i}].bidirectional must be boolean")
        if "inferenceConfidence" in c and c["inferenceConfidence"] is not None:
            ic = c["inferenceConfidence"]
            if not isinstance(ic, (int, float)) or ic < 0 or ic > 1:
                _audit("error", extra={"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", f"connections[{i}].inferenceConfidence must be between 0 and 1")
        inferred = c.get("inferred", False)
        if inferred is False and c.get("inferenceConfidence", None) is not None:
            _audit("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", f"connections[{i}].inferenceConfidence must be null when inferred=false")
        if inferred is True and "inferenceConfidence" in c and c["inferenceConfidence"] is None:
            # allowed (nullable), no error
            pass
        attrs = c.get("attributes")
        if attrs is not None:
            if not isinstance(attrs, dict):
                _audit("error", extra={"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", f"connections[{i}].attributes must be object")
            if "temporality" in attrs and attrs["temporality"] is not None and attrs["temporality"] not in allowed_temp:
                _audit("error", extra={"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", f"connections[{i}].attributes.temporality invalid")
            if "certainty" in attrs and attrs["certainty"] is not None and attrs["certainty"] not in allowed_cert:
                _audit("error", extra={"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", f"connections[{i}].attributes.certainty invalid")
            if "directionality" in attrs and attrs["directionality"] is not None and attrs["directionality"] not in allowed_dir:
                _audit("error", extra={"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", f"connections[{i}].attributes.directionality invalid")
            if "scope" in attrs and attrs["scope"] is not None and attrs["scope"] not in allowed_scope:
                _audit("error", extra={"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", f"connections[{i}].attributes.scope invalid")
            if "nature" in attrs and attrs["nature"] is not None and attrs["nature"] not in allowed_nature:
                _audit("error", extra={"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", f"connections[{i}].attributes.nature invalid")
            if "customAttributes" in attrs and attrs["customAttributes"] is not None:
                ca = attrs["customAttributes"]
                if not isinstance(ca, dict) or any((not isinstance(k, str) or not isinstance(vv, str)) for k, vv in ca.items()):
                    _audit("error", extra={"error_code": "VALIDATION_ERROR"})
                    return _err("VALIDATION_ERROR", f"connections[{i}].attributes.customAttributes must be a string->string object")

    # ---------- load store ----------
    users = _load("users.json")
    sessions = _load("sessions.json")
    thoughts = _load("thoughts.json")
    conns = _load("thought_connections.json")
    artifacts = _load("artifacts.json")

    if not isinstance(users, list): users = []
    if not isinstance(sessions, list): sessions = []
    if not isinstance(thoughts, list): thoughts = []
    if not isinstance(conns, list): conns = []
    if not isinstance(artifacts, list): artifacts = []

    # ---------- resolve/create user/session ----------
    user_row = None
    if userId is not None:
        for u in users:
            if isinstance(u, dict) and u.get("external_user_id") == userId and u.get("status") != "deleted":
                user_row = u
                break
        if user_row is None:
            # create user
            uid = _gen_id("usr")
            user_row = {
                "id": uid,
                "external_user_id": userId,
                "status": "active",
                "preferences": None,
                "created_at": now,
                "updated_at": now,
            }
            # unique external_user_id
            if any(isinstance(u, dict) and u.get("external_user_id") == userId for u in users):
                _audit("error", extra={"error_code": "CONFLICT"})
                return _err("CONFLICT", "external_user_id must be unique")
            users.append(user_row)

    session_row = None
    if sessionId is not None:
        for s in sessions:
            if isinstance(s, dict) and s.get("external_session_id") == sessionId:
                session_row = s
                break
    if session_row is None:
        # create session when missing OR sessionId not provided (new session id)
        sid_external = sessionId if sessionId is not None else _gen_id("sess_ext")
        if any(isinstance(s, dict) and s.get("external_session_id") == sid_external for s in sessions):
            # should not happen given lookup, but keep consistent
            _audit("error", extra={"error_code": "CONFLICT"})
            return _err("CONFLICT", "external_session_id must be unique")
        sid = _gen_id("sess")
        session_row = {
            "id": sid,
            "external_session_id": sid_external,
            "user_id": user_row["id"] if user_row else None,
            "status": "active",
            "default_suggest_tools": True,
            "default_help": True,
            "created_at": now,
            "updated_at": now,
            "closed_at": None,
        }
        sessions.append(session_row)
    else:
        # enforce session user binding if userId provided
        if user_row is not None:
            if session_row.get("user_id") is None:
                session_row["user_id"] = user_row["id"]
                session_row["updated_at"] = now
            else:
                if session_row.get("user_id") != user_row["id"] and session_row.get("status") == "active":
                    _audit("error", extra={"error_code": "CONFLICT"})
                    return _err("CONFLICT", "Cannot change user of an active session")
        # if session closed, still allow creating thoughts? schema allows; business rules don't forbid. Keep.

    # ---------- create thought ----------
    th_id = _gen_id("th")
    thought_row = {
        "id": th_id,
        "session_id": session_row["id"],
        "user_id": user_row["id"] if user_row else session_row.get("user_id"),
        "content": thought,
        "thought_type": thoughtType,
        "contains_calculations": bool(containsCalculations),
        "request_verification": bool(requestVerification),
        "request_suggestions": bool(requestSuggestions),
        "suggest_tools": bool(suggestTools),
        "help_requested": bool(help),
        "status": "created",
        "created_at": now,
        "updated_at": now,
    }
    thoughts.append(thought_row)

    # ---------- connections creation/reactivation ----------
    created_connections = []
    if connections:
        # build thought index for integrity checks
        thought_by_id = {t.get("id"): t for t in thoughts if isinstance(t, dict) and "id" in t}
        for c in connections:
            target_id = c["targetId"]
            if target_id == th_id:
                _audit("error", extra={"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "source_thought_id must be different from target_thought_id")
            target_th = thought_by_id.get(target_id)
            if target_th is None:
                _audit("error", extra={"error_code": "NOT_FOUND"})
                return _err("NOT_FOUND", "Target thought not found", thoughtId=target_id)

            # cross-session integrity
            if target_th.get("session_id") != session_row["id"]:
                _audit("error", extra={"error_code": "CONFLICT"})
                return _err("CONFLICT", "Cross-session connections are not allowed")

            ctype = c["type"]

            # check active unique constraint
            active_dup = None
            superseded_row = None
            deleted_row = None
            for r in conns:
                if not isinstance(r, dict):
                    continue
                if r.get("session_id") == session_row["id"] and r.get("source_thought_id") == th_id and r.get("target_thought_id") == target_id and r.get("connection_type") == ctype:
                    if r.get("status") == "active":
                        active_dup = r
                        break
                    if r.get("status") == "superseded":
                        superseded_row = r
                    if r.get("status") == "deleted":
                        deleted_row = r

            if active_dup is not None:
                # idempotent-ish: update mutable fields, keep active
                active_dup["strength"] = float(c["strength"])
                active_dup["description"] = c.get("description")
                attrs = c.get("attributes") or {}
                active_dup["temporality"] = attrs.get("temporality")
                active_dup["certainty"] = attrs.get("certainty")
                active_dup["directionality"] = attrs.get("directionality")
                active_dup["scope"] = attrs.get("scope")
                active_dup["nature"] = attrs.get("nature")
                active_dup["custom_attributes"] = (attrs.get("customAttributes") if isinstance(attrs.get("customAttributes"), dict) else None)
                active_dup["inferred"] = bool(c.get("inferred", False))
                active_dup["inference_confidence"] = c.get("inferenceConfidence")
                active_dup["bidirectional"] = bool(c.get("bidirectional", False))
                active_dup["updated_at"] = now
                created_connections.append(active_dup)
                continue

            if superseded_row is not None:
                # reactivate via allowed transition superseded -> active
                superseded_row["status"] = "active"
                superseded_row["strength"] = float(c["strength"])
                superseded_row["description"] = c.get("description")
                attrs = c.get("attributes") or {}
                superseded_row["temporality"] = attrs.get("temporality")
                superseded_row["certainty"] = attrs.get("certainty")
                superseded_row["directionality"] = attrs.get("directionality")
                superseded_row["scope"] = attrs.get("scope")
                superseded_row["nature"] = attrs.get("nature")
                superseded_row["custom_attributes"] = (attrs.get("customAttributes") if isinstance(attrs.get("customAttributes"), dict) else None)
                superseded_row["inferred"] = bool(c.get("inferred", False))
                superseded_row["inference_confidence"] = c.get("inferenceConfidence")
                superseded_row["bidirectional"] = bool(c.get("bidirectional", False))
                superseded_row["updated_at"] = now
                created_connections.append(superseded_row)
                continue

            if deleted_row is not None:
                # cannot transition deleted -> active; create new line
                pass

            attrs = c.get("attributes") or {}
            conn_row = {
                "id": _gen_id("conn"),
                "session_id": session_row["id"],
                "source_thought_id": th_id,
                "target_thought_id": target_id,
                "connection_type": ctype,
                "strength": float(c["strength"]),
                "description": c.get("description"),
                "temporality": attrs.get("temporality"),
                "certainty": attrs.get("certainty"),
                "directionality": attrs.get("directionality"),
                "scope": attrs.get("scope"),
                "nature": attrs.get("nature"),
                "custom_attributes": (attrs.get("customAttributes") if isinstance(attrs.get("customAttributes"), dict) else None),
                "inferred": bool(c.get("inferred", False)),
                "inference_confidence": c.get("inferenceConfidence"),
                "bidirectional": bool(c.get("bidirectional", False)),
                "status": "active",
                "created_at": now,
                "updated_at": now,
            }
            conns.append(conn_row)
            created_connections.append(conn_row)

    # ---------- artifacts creation/reset to requested ----------
    created_artifacts = []

    def _artifact_upsert(thought_id, artifact_type, viz_type=None, viz_options=None, request_flags=None):
        # unique(thought_id, artifact_type) where status in requested/generating/ready
        existing = None
        for a in artifacts:
            if not isinstance(a, dict):
                continue
            if a.get("thought_id") == thought_id and a.get("artifact_type") == artifact_type and a.get("status") in ("requested", "generating", "ready"):
                existing = a
                break

        if existing is not None:
            # reset to requested only if transition allows: failed/cancelled already excluded; generating/ requested ok; ready cannot go back.
            if existing.get("status") == "ready":
                return _err("INVALID_TRANSITION", "Artifact in status 'ready' cannot be reset to 'requested'", artifactId=existing.get("id"))
            if existing.get("status") == "generating":
                # generating -> requested not allowed
                return _err("INVALID_TRANSITION", "Artifact in status 'generating' cannot be reset to 'requested'", artifactId=existing.get("id"))
            # requested stays requested
            existing["status"] = "requested"
            existing["request_flags"] = request_flags
            if artifact_type == "visualization":
                existing["visualization_type"] = viz_type
                existing["visualization_options"] = viz_options
            existing["updated_at"] = now
            created_artifacts.append(existing)
            return None

        # create new
        arow = {
            "id": _gen_id("art"),
            "session_id": session_row["id"],
            "thought_id": thought_id,
            "artifact_type": artifact_type,
            "status": "requested",
            "request_flags": request_flags,
            "visualization_type": viz_type if artifact_type == "visualization" else None,
            "visualization_options": viz_options if artifact_type == "visualization" else None,
            "result_payload": None,
            "error_message": None,
            "created_at": now,
            "updated_at": now,
        }
        # enforce visualization constraint
        if artifact_type == "visualization" and not arow["visualization_type"]:
            return _err("VALIDATION_ERROR", "visualization_type is required for visualization artifact")
        if artifact_type != "visualization" and arow["visualization_type"] is not None:
            return _err("VALIDATION_ERROR", "visualization_type must be null when artifact_type != 'visualization'")
        artifacts.append(arow)
        created_artifacts.append(arow)
        return None

    flags = {
        "help": bool(help),
        "requestSuggestions": bool(requestSuggestions),
        "requestVerification": bool(requestVerification),
        "generateVisualization": bool(generateVisualization),
        "suggestTools": bool(suggestTools),
        "containsCalculations": bool(containsCalculations),
    }

    if generateVisualization:
        e = _artifact_upsert(th_id, "visualization", viz_type=visualizationType or "graph", viz_options=visualizationOptions, request_flags=flags)
        if e:
            _audit("error", extra={"error_code": e["error"]["code"]})
            return e
    if requestSuggestions:
        e = _artifact_upsert(th_id, "suggestions", request_flags=flags)
        if e:
            _audit("error", extra={"error_code": e["error"]["code"]})
            return e
    if requestVerification or containsCalculations:
        e = _artifact_upsert(th_id, "verification", request_flags=flags)
        if e:
            _audit("error", extra={"error_code": e["error"]["code"]})
            return e
    if help:
        e = _artifact_upsert(th_id, "help", request_flags=flags)
        if e:
            _audit("error", extra={"error_code": e["error"]["code"]})
            return e

    # ---------- persist ----------
    _save("users.json", users)
    _save("sessions.json", sessions)
    _save("thoughts.json", thoughts)
    _save("thought_connections.json", conns)
    _save("artifacts.json", artifacts)

    _audit("ok")

    return {
        "session": {
            "id": session_row["id"],
            "sessionId": session_row["external_session_id"],
            "status": session_row["status"],
            "user_id": session_row.get("user_id"),
            "created_at": session_row["created_at"],
            "updated_at": session_row["updated_at"],
        },
        "user": (None if user_row is None else {
            "id": user_row["id"],
            "userId": user_row["external_user_id"],
            "status": user_row["status"],
            "preferences": user_row.get("preferences"),
            "created_at": user_row["created_at"],
            "updated_at": user_row["updated_at"],
