def smartthinking_whoami(authToken, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0400000" if __import__("os").path.isdir("./environment_mix/0400000") else "/app/database")
    def _load(n):
