        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _audit(status_s, used_auth=None, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": _gen_id("req"),
            "endpoint": "smartthinking_whoami",
            "status": status_s,
            "latency_ms": latency_ms,
            "timestamp": now,
            "auth_token": used_auth,
        }
        if error_code:
            row["error_code"] = error_code
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate
    if not isinstance(authToken, str) or not authToken.strip():
        _audit("error", used_auth=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "authToken must be a non-empty string.", field="authToken")

    # Authenticate: in this simplified datastore, authToken corresponds to a user id or external_user_id.
    users = _load("users.json")
    if not isinstance(users, list):
        users = []
    user = next((u for u in users if u.get("id") == authToken or u.get("external_user_id") == authToken), None)
    if not user:
        _audit("error", used_auth=authToken, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid or expired auth token.")

    if user.get("status") != "active":
        _audit("error", used_auth=authToken, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Account is not active.", userId=user.get("external_user_id"), status=user.get("status"))

    # Quota/rate-limit: schema does not declare limits; still return usage metadata from logs.
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    # Compute last-minute request count for this token
    minute_ago = now_dt - datetime.timedelta(seconds=60)

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        s = ts[:-1] if ts.endswith("Z") else ts
        try:
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    last_min = 0
    total = 0
    for r in logs:
        if r.get("auth_token") != authToken:
            continue
        total += 1
        dt = _parse_ts(r.get("timestamp"))
        if dt and dt >= minute_ago:
            last_min += 1

    _audit("ok", used_auth=authToken, error_code=None)
    return {
        "user": {
            "id": user.get("id"),
            "userId": user.get("external_user_id"),
            "status": user.get("status"),
            "preferences": user.get("preferences"),
            "created_at": user.get("created_at"),
            "updated_at": user.get("updated_at"),
        },
        "scopes": ["thoughts:read", "thoughts:write", "artifacts:read", "artifacts:write"],
        "usage": {
            "requests_total": total,
            "requests_last_minute": last_min,
            "rate_limit": None,
            "quota": None,
        },
    }

def smartthinking_listThoughts(authToken, sessionId=None, userId=None, status=None, thoughtType=None, search=None, createdAfter=None, createdBefore=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0400000" if __import__("os").path.isdir("./environment_mix/0400000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _audit(status_s, used_auth=None, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": _gen_id("req"),
            "endpoint": "smartthinking_listThoughts",
            "status": status_s,
            "latency_ms": latency_ms,
            "timestamp": now,
            "auth_token": used_auth,
        }
        if error_code:
            row["error_code"] = error_code
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    # ---- validate authToken ----
    if not isinstance(authToken, str) or not authToken.strip():
        _audit("error", used_auth=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "authToken must be a non-empty string.", field="authToken")

    users = _load("users.json")
    if not isinstance(users, list):
        users = []
    authed_user = next((u for u in users if u.get("id") == authToken or u.get("external_user_id") == authToken), None)
    if not authed_user or authed_user.get("status") != "active":
        _audit("error", used_auth=authToken, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid or expired auth token.")

    # ---- validate filters (be permissive with bad values: treat as validation error only when schema requires) ----
    if sessionId is not None and (not isinstance(sessionId, str) or not sessionId.strip()):
        _audit("error", used_auth=authToken, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sessionId must be a non-empty string when provided.", field="sessionId")
    if userId is not None and (not isinstance(userId, str) or not userId.strip()):
        _audit("error", used_auth=authToken, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "userId must be a non-empty string when provided.", field="userId")

    if status is not None and status not in ["created", "enriched", "archived", "deleted"]:
        _audit("error", used_auth=authToken, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid status filter.", field="status")
    if thoughtType is not None and thoughtType not in ["regular", "revision", "meta", "hypothesis", "conclusion"]:
        _audit("error", used_auth=authToken, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid thoughtType filter.", field="thoughtType")
    if search is not None and not isinstance(search, str):
        _audit("error", used_auth=authToken, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "search must be a string.", field="search")

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        _audit("error", used_auth=authToken, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer.", field="limit")
    if limit < 1 or limit > 200:
        _audit("error", used_auth=authToken, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200.", field="limit")

    if sort is None:
        sort = "created_at_desc"
    if sort not in ["created_at_asc", "created_at_desc", "updated_at_asc", "updated_at_desc"]:
        _audit("error", used_auth=authToken, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid sort value.", field="sort")

    def _parse_iso(ts):
        if ts is None:
            return None
        if not isinstance(ts, str):
            return None
        s = ts.strip()
        if s.endswith("Z"):
            s = s[:-1]
        try:
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    ca = _parse_iso(createdAfter)
    if createdAfter is not None and ca is None:
        _audit("error", used_auth=authToken, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "createdAfter must be an ISO-8601 datetime string.", field="createdAfter")
    cb = _parse_iso(createdBefore)
    if createdBefore is not None and cb is None:
        _audit("error", used_auth=authToken, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "createdBefore must be an ISO-8601 datetime string.", field="createdBefore")

    # ---- resolve optional session/user context ----
    sessions = _load("sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    resolved_session = None
    if sessionId is not None:
        resolved_session = next((s for s in sessions if s.get("external_session_id") == sessionId), None)
        if not resolved_session:
            _audit("error", used_auth=authToken, error_code="NOT_FOUND")
            return _err("NOT_FOUND", "Session not found.", sessionId=sessionId)

        # access control: if session has user_id set, it must match authed user
        sess_user_id = resolved_session.get("user_id")
        if sess_user_id is not None and sess_user_id != authed_user.get("id"):
            _audit("error", used_auth=authToken, error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Session not accessible to current user.", sessionId=sessionId)

    resolved_user = None
    if userId is not None:
        resolved_user = next((u for u in users if u.get("external_user_id") == userId), None)
        if not resolved_user:
            # filter matches nothing -> return empty set (not error), but only if session access ok
            resolved_user = None

    # ---- list thoughts ----
    thoughts = _load("thoughts.json")
    if not isinstance(thoughts, list):
        thoughts = []

    def _dt_field(row, fld):
        dt = _parse_iso(row.get(fld))
        return dt

    # Cursor: opaque base64 json {"v":1,"sort":sort,"after":<iso>,"after_id":<id>}
    after_dt = None
    after_id = None
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.strip():
            _audit("error", used_auth=authToken, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.", field="cursor")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            payload = json.loads(raw.decode("utf-8"))
        except Exception:
            _audit("error", used_auth=authToken, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
        if not isinstance(payload, dict) or payload.get("v") != 1:
            _audit("error", used_auth=authToken, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
        if payload.get("sort") != sort:
            _audit("error", used_auth=authToken, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Cursor sort mismatch.", field="cursor")
        after_dt = _parse_iso(payload.get("after"))
        after_id = payload.get("after_id")
        if after_dt is None or not isinstance(after_id, str):
            _audit("error", used_auth=authToken, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    # Filter
    rows = []
    for th in thoughts:
        # session scope
        if resolved_session is not None:
            if th.get("session_id") != resolved_session.get("id"):
                continue

        # user scope: if userId provided, filter by that user internal id
        if userId is not None:
            if not resolved_user:
                continue  # unknown external user => empty result set
            if th.get("user_id") != resolved_user.get("id"):
                continue
        else:
            # if session not provided, default to authed user only (privacy)
            if resolved_session is None:
                if th.get("user_id") != authed_user.get("id"):
                    continue

        if status is not None and th.get("status") != status:
            continue
        if thoughtType is not None and th.get("thought_type") != thoughtType:
            continue
        if search is not None:
            c = th.get("content") or ""
            if not isinstance(c, str):
                c = str(c)
            if search.lower() not in c.lower():
                continue
        if ca is not None:
            dtc = _dt_field(th, "created_at")
            if not dtc or dtc <= ca:
                continue
        if cb is not None:
            dtc = _dt_field(th, "created_at")
            if not dtc or dtc >= cb:
                continue

        rows.append(th)

    # Sort
    reverse = sort.endswith("_desc")
    key_field = "created_at" if sort.startswith("created_at") else "updated_at"

    def _sort_key(r):
        dtv = _dt_field(r, key_field)
        # Ensure deterministic ordering with id
        return (dtv or datetime.datetime(1970, 1, 1), r.get("id") or "")

    rows.sort(key=_sort_key, reverse=reverse)

    # Apply cursor window
    if after_dt is not None and after_id is not None:
        filtered = []
        for r in rows:
            dtv = _dt_field(r, key_field) or datetime.datetime(1970, 1, 1)
            rid = r.get("id") or ""
            if reverse:
                # descending: take items strictly "before" the cursor
                if (dtv < after_dt) or (dtv == after_dt and rid < after_id):
                    filtered.append(r)
            else:
                # ascending: take items strictly "after" the cursor
                if (dtv > after_dt) or (dtv == after_dt and rid > after_id):
                    filtered.append(r)
        rows = filtered

    total = len(rows)
    page = rows[:limit]
    has_more = total > limit

    next_cursor = None
    if has_more and page:
        last = page[-1]
        last_dt = _dt_field(last, key_field) or datetime.datetime(1970, 1, 1)
        payload = {"v": 1, "sort": sort, "after": last_dt.replace(microsecond=0).isoformat() + "Z", "after_id": last.get("id")}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    _audit("ok", used_auth=authToken, error_code=None)
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort,
        },
    }

def smartthinking_getThought(authToken, thoughtId, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0400000" if __import__("os").path.isdir("./environment_mix/0400000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _audit(status_s, used_auth=None, error_code=None, meta=None):
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{latency_ms}",
            "endpoint": "smartthinking_getThought",
            "status": status_s,
            "latency_ms": latency_ms,
            "timestamp": now,
            "auth_token": used_auth,
        }
        if error_code:
            row["error_code"] = error_code
        if meta is not None:
            row["meta"] = meta
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate inputs
    if not isinstance(authToken, str) or not authToken.strip():
        _audit("error", used_auth=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "authToken must be a non-empty string.", field="authToken")
    if not isinstance(thoughtId, str) or not thoughtId.strip():
        _audit("error", used_auth=authToken, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "thoughtId must be a non-empty string.", field="thoughtId")

    # Authenticate: token matches an existing user id OR external_user_id.
    # Do not require "active": disabled users can still read their data; deleted accounts are unauthorized.
    users = _load("users.json")
    if not isinstance(users, list):
        users = []
    authed_user = None
    for u in users:
        if u.get("id") == authToken or u.get("external_user_id") == authToken:
            if u.get("status") == "deleted":
                authed_user = None
            else:
                authed_user = u
            break
    if not authed_user:
        _audit("error", used_auth=authToken, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid authToken.", authToken=authToken)

    thoughts = _load("thoughts.json")
    if not isinstance(thoughts, list):
        thoughts = []
    thought = None
    for t in thoughts:
        if t.get("id") == thoughtId:
            thought = t
            break

    if not thought:
        # True "unknown id" should be NOT_FOUND.
        _audit("error", used_auth=authToken, error_code="NOT_FOUND", meta={"thoughtId": thoughtId})
        return _err("NOT_FOUND", "Thought not found.", thoughtId=thoughtId)

    # Access control: if thought.user_id is set, it must match the authenticated user.
    # If thought.user_id is null, it's readable by any authenticated user.
    if thought.get("user_id") is not None and thought.get("user_id") != authed_user.get("id"):
        _audit("error", used_auth=authToken, error_code="UNAUTHORIZED", meta={"thoughtId": thoughtId})
        return _err("UNAUTHORIZED", "Not allowed to access this thought.", thoughtId=thoughtId)

    # Enrich: return edges and artifacts linked to the thought
    edges = _load("thought_connections.json")
    if not isinstance(edges, list):
        edges = []
    artifacts = _load("artifacts.json")
    if not isinstance(artifacts, list):
        artifacts = []

    thought_edges = [e for e in edges if e.get("source_thought_id") == thoughtId and e.get("status") != "deleted"]
    thought_artifacts = [a for a in artifacts if a.get("thought_id") == thoughtId]

    result = {
        "thought": thought,
        "connections": thought_edges,
        "artifacts": thought_artifacts,
    }
    _audit("ok", used_auth=authToken)
    return result

def smartthinking_updateThought(authToken, thoughtId, content=None, thoughtType=None, status=None, requestVerification=None, containsCalculations=None, requestSuggestions=None, suggestTools=None, helpRequested=None, generateVisualization=None, visualizationType=None, visualizationOptions=None, **_extra):
