            "auth_token": used_auth,
        }
        if error_code:
            row["error_code"] = error_code
        if meta is not None:
            row["meta"] = meta
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    def _json_size_bytes(obj):
        return len(json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8"))

    def _gen_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%y%m%d%H%M%S')}_{uuid.uuid4().hex[:16]}"

    # Validate base
    if not isinstance(authToken, str) or not authToken.strip():
        _audit("error", used_auth=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "authToken must be a non-empty string.", field="authToken")
    if not isinstance(thoughtId, str) or not thoughtId.strip():
        _audit("error", used_auth=authToken, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "thoughtId must be a non-empty string.", field="thoughtId")

    allowed_thought_types = ["regular", "revision", "meta", "hypothesis", "conclusion"]
    allowed_statuses = ["created", "enriched", "archived", "deleted"]
    if content is not None:
        if not isinstance(content, str):
            _audit("error", used_auth=authToken, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "content must be a string.", field="content")
        if len(content) > 20000:
            _audit("error", used_auth=authToken, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "content exceeds 20000 characters.", field="content", maxLength=20000)
        if content == "":
            _audit("error", used_auth=authToken, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "content must be non-empty.", field="content")
    if thoughtType is not None:
        if thoughtType not in allowed_thought_types:
            _audit("error", used_auth=authToken, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid thoughtType.", field="thoughtType", allowed=allowed_thought_types)
    if status is not None:
        if status not in allowed_statuses:
            _audit("error", used_auth=authToken, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid status.", field="status", allowed=allowed_statuses)

    for fname, val in [
        ("requestVerification", requestVerification),
        ("containsCalculations", containsCalculations),
        ("requestSuggestions", requestSuggestions),
        ("suggestTools", suggestTools),
        ("helpRequested", helpRequested),
        ("generateVisualization", generateVisualization),
    ]:
