            _audit("error", used_auth=authToken, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"{fname} must be a boolean.", field=fname)

    if visualizationType is not None:
        allowed_viz = ["graph", "chronological", "thematic", "hierarchical", "force", "radial"]
        if visualizationType not in allowed_viz:
            _audit("error", used_auth=authToken, error_code="VALIDATION_ERROR")
