        return _err("VALIDATION_ERROR", "visualizationOptions must be an object.", field="visualizationOptions")

    if visualizationOptions is not None and _json_size_bytes(visualizationOptions) > 64 * 1024:
        _audit("error", used_auth=authToken, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "visualizationOptions exceeds 64KB when serialized.", field="visualizationOptions", maxBytes=65536)

    # Authenticate: token matches user id OR external_user_id; deleted users unauthorized.
    users = _load("users.json")
    if not isinstance(users, list):
        users = []
    authed_user = None
    for u in users:
        if u.get("id") == authToken or u.get("external_user_id") == authToken:
            if u.get("status") == "deleted":
                authed_user = None
            else:
                authed_user = u
            break
    if not authed_user:
        _audit("error", used_auth=authToken, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid authToken.", authToken=authToken)

    thoughts = _load("thoughts.json")
    if not isinstance(thoughts, list):
        thoughts = []
    idx = None
    for i, t in enumerate(thoughts):
        if t.get("id") == thoughtId:
            idx = i
            break
    if idx is None:
        _audit("error", used_auth=authToken, error_code="NOT_FOUND", meta={"thoughtId": thoughtId})
        return _err("NOT_FOUND", "Thought not found.", thoughtId=thoughtId)

    thought = thoughts[idx]

    # Access control
    if thought.get("user_id") is not None and thought.get("user_id") != authed_user.get("id"):
        _audit("error", used_auth=authToken, error_code="UNAUTHORIZED", meta={"thoughtId": thoughtId})
        return _err("UNAUTHORIZED", "Not allowed to modify this thought.", thoughtId=thoughtId)

    # Refuse if thought already deleted (business rule)
    if thought.get("status") == "deleted":
        _audit("error", used_auth=authToken, error_code="INVALID_TRANSITION", meta={"thoughtId": thoughtId})
        return _err("INVALID_TRANSITION", "Cannot update a deleted thought.", thoughtId=thoughtId)

    # Apply updates + enforce lifecycle transitions
    transitions = {
        "created": ["enriched", "archived", "deleted"],
        "enriched": ["archived", "deleted"],
        "archived": ["enriched", "deleted"],
        "deleted": [],
    }

    changed = False
    if content is not None and content != thought.get("content"):
        thought["content"] = content
        changed = True
    if thoughtType is not None and thoughtType != thought.get("thought_type"):
        thought["thought_type"] = thoughtType
        changed = True
    if requestVerification is not None and requestVerification != thought.get("request_verification"):
        thought["request_verification"] = requestVerification
        changed = True
    if containsCalculations is not None and containsCalculations != thought.get("contains_calculations"):
        thought["contains_calculations"] = containsCalculations
        changed = True
    if requestSuggestions is not None and requestSuggestions != thought.get("request_suggestions"):
        thought["request_suggestions"] = requestSuggestions
        changed = True
    if suggestTools is not None and suggestTools != thought.get("suggest_tools"):
        thought["suggest_tools"] = suggestTools
        changed = True
    if helpRequested is not None and helpRequested != thought.get("help_requested"):
        thought["help_requested"] = helpRequested
        changed = True

    if status is not None and status != thought.get("status"):
        cur = thought.get("status")
        if cur not in transitions or status not in transitions.get(cur, []):
            _audit("error", used_auth=authToken, error_code="INVALID_TRANSITION", meta={"from": cur, "to": status, "thoughtId": thoughtId})
            return _err("INVALID_TRANSITION", "Invalid thought status transition.", from_status=cur, to_status=status, thoughtId=thoughtId)
        thought["status"] = status
        changed = True

    # Artifact (re)triggers based on updated flags
    artifacts = _load("artifacts.json")
    if not isinstance(artifacts, list):
        artifacts = []

    def _upsert_artifact(artifact_type, allow_reset_from, desired_status, extra_fields=None):
        # unique(thought_id, artifact_type) where status in ('requested','generating','ready')
        nonlocal artifacts, changed
        active_statuses = {"requested", "generating", "ready"}
        existing_idx = None
        for i, a in enumerate(artifacts):
            if a.get("thought_id") == thoughtId and a.get("artifact_type") == artifact_type and a.get("status") in active_statuses:
                existing_idx = i
                break
        if existing_idx is None:
            # create new
            art = {
                "id": _gen_id("st_art"),
                "session_id": thought.get("session_id"),
                "thought_id": thoughtId,
                "artifact_type": artifact_type,
                "status": desired_status,
                "request_flags": None,
                "visualization_type": None,
                "visualization_options": None,
                "result_payload": None,
                "error_message": None,
                "created_at": now,
                "updated_at": now,
            }
            if extra_fields:
                for k, v in extra_fields.items():
                    art[k] = v
            artifacts.append(art)
            changed = True
            return art
        else:
            art = artifacts[existing_idx]
            cur_s = art.get("status")
            if cur_s == desired_status:
                # Idempotent: still refresh request_flags if provided via extra_fields
                did = False
                if extra_fields:
                    for k, v in extra_fields.items():
                        if art.get(k) != v:
                            art[k] = v
                            did = True
                if did:
                    art["updated_at"] = now
                    changed = True
                return art

            if cur_s not in allow_reset_from:
                # not allowed to jump (e.g. ready -> generating or ready -> requested)
                return _err("INVALID_TRANSITION", f"Invalid artifact status transition for {artifact_type}.", artifactId=art.get("id"), from_status=cur_s, to_status=desired_status)

            art["status"] = desired_status
            art["updated_at"] = now
            if desired_status == "requested":
                art["error_message"] = None
                art["result_payload"] = None
            if extra_fields:
                for k, v in extra_fields.items():
                    art[k] = v
            changed = True
            return art

    # Prepare request_flags snapshot if we create/reset artifacts
    req_flags_snapshot = {
        "help": bool(thought.get("help_requested")),
        "requestSuggestions": bool(thought.get("request_suggestions")),
        "requestVerification": bool(thought.get("request_verification")),
        "containsCalculations": bool(thought.get("contains_calculations")),
        "suggestTools": bool(thought.get("suggest_tools")),
        "generateVisualization": bool(generateVisualization) if generateVisualization is not None else False,
    }

    # Suggestions
    if thought.get("request_suggestions") is True:
        res = _upsert_artifact(
            "suggestions",
            allow_reset_from={"failed", "cancelled", "requested"},
            desired_status="requested",
            extra_fields={"request_flags": req_flags_snapshot},
        )
        if isinstance(res, dict) and res.get("error"):
            _audit("error", used_auth=authToken, error_code=res["error"]["code"])
            return res

    # Verification
    if thought.get("request_verification") is True or thought.get("contains_calculations") is True:
        res = _upsert_artifact(
            "verification",
            allow_reset_from={"failed", "cancelled", "requested"},
            desired_status="requested",
            extra_fields={"request_flags": req_flags_snapshot},
        )
        if isinstance(res, dict) and res.get("error"):
            _audit("error", used_auth=authToken, error_code=res["error"]["code"])
            return res

    # Help (unique active per thought)
    if thought.get("help_requested") is True:
        res = _upsert_artifact(
            "help",
            allow_reset_from={"failed", "cancelled", "requested"},
            desired_status="requested",
            extra_fields={"request_flags": req_flags_snapshot},
        )
        if isinstance(res, dict) and res.get("error"):
            _audit("error", used_auth=authToken, error_code=res["error"]["code"])
            return res

    # Visualization
    if generateVisualization is True:
        viz_type = visualizationType if visualizationType is not None else "graph"
        viz_opts = visualizationOptions if visualizationOptions is not None else None
        if viz_opts is not None and _json_size_bytes(viz_opts) > 64 * 1024:
            _audit("error", used_auth=authToken, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "visualizationOptions exceeds 64KB when serialized.", field="visualizationOptions", maxBytes=65536)

        res = _upsert_artifact(
            "visualization",
            allow_reset_from={"failed", "cancelled", "requested"},
            desired_status="requested",
            extra_fields={
                "visualization_type": viz_type,
                "visualization_options": viz_opts,
                "request_flags": req_flags_snapshot,
            },
        )
        if isinstance(res, dict) and res.get("error"):
            _audit("error", used_auth=authToken, error_code=res["error"]["code"])
            return res

    if changed:
        thought["updated_at"] = now
        thoughts[idx] = thought
        _save("thoughts.json", thoughts)
        _save("artifacts.json", artifacts)
    else:
        # No success without effect for mutation
        _audit("error", used_auth=authToken, error_code="CONFLICT", meta={"thoughtId": thoughtId})
        return _err("CONFLICT", "No changes to apply.", thoughtId=thoughtId)

    _audit("ok", used_auth=authToken, meta={"thoughtId": thoughtId})
    return {"thought": thought, "artifacts": [a for a in artifacts if a.get("thought_id") == thoughtId]}

def smartthinking_listArtifacts(authToken, sessionId=None, thoughtId=None, artifactType=None, status=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time, base64

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0400000" if __import__("os").path.isdir("./environment_mix/0400000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _parse_cursor(c):
        if c is None:
            return None
        if not isinstance(c, str) or not c.strip():
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.", field="cursor")
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or "offset" not in obj:
                return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
            off = obj["offset"]
            if not isinstance(off, int) or off < 0:
                return _err("VALIDATION_ERROR", "Invalid cursor offset.", field="cursor")
            return off
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor encoding.", field="cursor")

    def _make_cursor(offset):
        raw = json.dumps({"offset": offset}, separators=(",", ":"))
        return base64.urlsafe_b64encode(raw.encode("utf-8")).decode("utf-8")

    # auth: no auth table; accept any non-empty token
    if not isinstance(authToken, str) or not authToken.strip():
        return _err("UNAUTHORIZED", "Invalid authToken.")

    if sessionId is not None and (not isinstance(sessionId, str) or not sessionId.strip()):
        return _err("VALIDATION_ERROR", "sessionId must be a non-empty string.", field="sessionId")

    if thoughtId is not None and (not isinstance(thoughtId, str) or not thoughtId.strip()):
        return _err("VALIDATION_ERROR", "thoughtId must be a non-empty string.", field="thoughtId")

    if artifactType is not None and artifactType not in ["suggestions", "verification", "visualization", "help"]:
        return _err("VALIDATION_ERROR", "Invalid artifactType.", field="artifactType")

    if status is not None and status not in ["requested", "generating", "ready", "failed", "cancelled"]:
        return _err("VALIDATION_ERROR", "Invalid status.", field="status")

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer.", field="limit")
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200.", field="limit", minimum=1, maximum=200)

    if sort is None:
        sort = "created_at_desc"
    if sort not in ["created_at_asc", "created_at_desc", "updated_at_asc", "updated_at_desc"]:
        return _err("VALIDATION_ERROR", "Invalid sort.", field="sort")

    off = 0
    if cursor is not None:
        parsed = _parse_cursor(cursor)
        if isinstance(parsed, dict) and parsed.get("error"):
            return parsed
        off = parsed

    artifacts = _load("artifacts.json")
    sessions = _load("sessions.json")
    thoughts = _load("thoughts.json")

    # Resolve session if provided
    session_row = None
    if sessionId is not None:
        session_row = next((s for s in sessions if s.get("external_session_id") == sessionId), None)
        if session_row is None:
            # list read with filter matching nothing -> empty set (not error)
            latency_ms = int((time.time() - _t0) * 1000)
            return {
                "artifacts": [],
                "meta": {"total": 0, "limit": limit, "has_more": False, "next_cursor": None, "latency_ms": latency_ms}
            }

    thought_row = None
    if thoughtId is not None:
        thought_row = next((t for t in thoughts if t.get("id") == thoughtId), None)
        if thought_row is None:
            latency_ms = int((time.time() - _t0) * 1000)
            return {
                "artifacts": [],
                "meta": {"total": 0, "limit": limit, "has_more": False, "next_cursor": None, "latency_ms": latency_ms}
            }
        if session_row is not None and thought_row.get("session_id") != session_row.get("id"):
            return _err("VALIDATION_ERROR", "thoughtId does not belong to the provided sessionId.", field="thoughtId")

    # Filter
    rows = artifacts
    if session_row is not None:
        sid = session_row.get("id")
        rows = [a for a in rows if a.get("session_id") == sid]
    if thought_row is not None:
        tid = thought_row.get("id")
        rows = [a for a in rows if a.get("thought_id") == tid]
    if artifactType is not None:
        rows = [a for a in rows if a.get("artifact_type") == artifactType]
    if status is not None:
        rows = [a for a in rows if a.get("status") == status]

    # Sort
    key_field, direction = sort.rsplit("_", 1)
    reverse = (direction == "desc")

    def _key(a):
        v = a.get(key_field)
        return v if isinstance(v, str) else ""

    rows.sort(key=_key, reverse=reverse)

    total = len(rows)
    page = rows[off:off + limit]
    next_off = off + len(page)
    has_more = next_off < total
    next_cursor = _make_cursor(next_off) if has_more else None

    latency_ms = int((time.time() - _t0) * 1000)

    return {
        "artifacts": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "latency_ms": latency_ms
        }
    }

def smartthinking_updateArtifact(authToken, artifactId, status, requestFlags=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0400000" if __import__("os").path.isdir("./environment_mix/0400000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _audit(status_s, used_auth=None, error_code=None, meta=None):
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{latency_ms}",
            "endpoint": "smartthinking_updateArtifact",
            "status": status_s,
            "latency_ms": latency_ms,
            "timestamp": now,
            "auth_token": used_auth,
        }
        if error_code:
            row["error_code"] = error_code
        if meta is not None:
            row["meta"] = meta
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate
    if not isinstance(authToken, str) or not authToken.strip():
        _audit("error", used_auth=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "authToken must be a non-empty string.", field="authToken")
    if not isinstance(artifactId, str) or not artifactId.strip():
        _audit("error", used_auth=authToken, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "artifactId must be a non-empty string.", field="artifactId")
    allowed = ["requested", "generating", "ready", "failed", "cancelled"]
    if status not in allowed:
        _audit("error", used_auth=authToken, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid status.", field="status", allowed=allowed)
    if requestFlags is not None and not isinstance(requestFlags, dict):
        _audit("error", used_auth=authToken, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "requestFlags must be an object.", field="requestFlags")

    # Authenticate
    users = _load("users.json")
    if not isinstance(users, list):
        users = []
    authed_user = None
    for u in users:
        if u.get("id") == authToken or u.get("external_user_id") == authToken:
            if u.get("status") == "deleted":
                authed_user = None
            else:
                authed_user = u
            break
    if not authed_user:
        _audit("error", used_auth=authToken, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid authToken.", authToken=authToken)

    artifacts = _load("artifacts.json")
    if not isinstance(artifacts, list):
        artifacts = []

    idx = None
    for i, a in enumerate(artifacts):
        if a.get("id") == artifactId:
            idx = i
            break
    if idx is None:
        _audit("error", used_auth=authToken, error_code="NOT_FOUND", meta={"artifactId": artifactId})
        return _err("NOT_FOUND", "Artifact not found.", artifactId=artifactId)

    art = artifacts[idx]

    # Access control via thought.user_id if present
    thoughts = _load("thoughts.json")
    if not isinstance(thoughts, list):
        thoughts = []
    thought = None
    for t in thoughts:
        if t.get("id") == art.get("thought_id"):
            thought = t
            break
    if thought and thought.get("user_id") is not None and thought.get("user_id") != authed_user.get("id"):
        _audit("error", used_auth=authToken, error_code="UNAUTHORIZED", meta={"artifactId": artifactId})
        return _err("UNAUTHORIZED", "Not allowed to modify this artifact.", artifactId=artifactId)

    transitions = {
        "requested": ["generating", "cancelled"],
        "generating": ["ready", "failed", "cancelled"],
        "ready": [],
        "failed": ["requested"],
        "cancelled": ["requested"],
    }

    cur = art.get("status")
    if cur not in transitions:
        _audit("error", used_auth=authToken, error_code="CONFLICT", meta={"artifactId": artifactId, "status": cur})
        return _err("CONFLICT", "Artifact has unknown current status.", artifactId=artifactId, current_status=cur)

    if status != cur:
        if status not in transitions[cur]:
            _audit("error", used_auth=authToken, error_code="INVALID_TRANSITION", meta={"artifactId": artifactId, "from": cur, "to": status})
            return _err("INVALID_TRANSITION", "Invalid artifact status transition.", artifactId=artifactId, from_status=cur, to_status=status)

        art["status"] = status
        art["updated_at"] = now
        if status == "requested":
            art["error_message"] = None
            art["result_payload"] = None
        changed = True
    else:
        changed = False

    if requestFlags is not None:
        if art.get("request_flags") != requestFlags:
            art["request_flags"] = requestFlags
            art["updated_at"] = now
            changed = True

    if not changed:
        _audit("error", used_auth=authToken, error_code="CONFLICT", meta={"artifactId": artifactId})
        return _err("CONFLICT", "No changes to apply.", artifactId=artifactId)

    artifacts[idx] = art
    _save("artifacts.json", artifacts)
    _audit("ok", used_auth=authToken, meta={"artifactId": artifactId})
    return {"artifact": art}
